// Regenerate the multi-event season fixtures for season-leaderboard tests.
//
// Run from apps/web (also runs automatically as `pretest`):
//   node tests/fixtures/build-multi-event-season.mjs
//
// Output: tests/fixtures/season-event-{1..5}.axdb (gitignored — regenerated by `pnpm pretest`).
//
// The data is entirely synthetic — see feedback_sensitive_axdb_fixtures memory.
//
// Ingest reads one event per .axdb file. We create 5 separate files (one per
// season event) so the test can ingest all 5 and call buildSeasonLeaderboard.
// Drivers with the same member_num are upserted to the same Driver record.
//
// Scenario (2026 season, classes C1 / CS):
//
//  Driver 1: Alex Arena    (member MES-001, C1 every event) — 5 events; best-4-of-5
//  Driver 2: Bea Barton    (member MES-002, C1 events 1-4, CS event 5) — season class C1
//  Driver 3: Cam Crane     (member MES-003, CS events 1-3 only) — provisional (3 < 4)
//  Driver 4: Dee Dumas     (member MES-004, C1 events 1-2, CS events 3-4) — 2+2 tie → C1 (earliest)
//  Driver 5: Evan Elias    (member MES-005, C1 event 1 only) — provisional (1 < 4)
//
// Cone math uses CONE_PENALTY_MS = 2000 (raw times stored as finish_tick - start_tick).
// Alex's event 5 run: raw=54000ms + 1 cone → corrected=56000ms (only C1 scorer → 1000 pts).
//
// bestcommittedrun override (M1.12): event 3, Cam has two runs:
//   R1=59000ms (committed), R2=57000ms (faster clean).
//   ingest should honor R1=59000ms as Cam's best at event 3.
//   All other driver-events: bestcommittedrun_no points to their single (and fastest) run.
//
// Scoring assertions (documented in season-leaderboard.test.ts):
//
//  Event 1 / C1  fastest = 50000ms (Alex) → 1000 pts
//             Bea   55000ms → round(1000 * 50000 / 55000) = 909
//             Dee   60000ms → round(1000 * 50000 / 60000) = 833
//             Evan  62000ms → round(1000 * 50000 / 62000) = 806
//  Event 1 / CS  fastest = 57000ms (Cam)  → 1000 pts
//
//  Event 2 / C1  fastest = 51000ms (Alex) → 1000 pts
//             Bea   53000ms → round(1000 * 51000 / 53000) = 962
//             Dee   56000ms → round(1000 * 51000 / 56000) = 911
//  Event 2 / CS  fastest = 58000ms (Cam)  → 1000 pts
//
//  Event 3 / C1  fastest = 52000ms (Alex) → 1000 pts
//             Bea   54000ms → round(1000 * 52000 / 54000) = 963
//  Event 3 / CS  Cam committed=59000ms (R1), Dee=61000ms
//             fastest = 59000ms (Cam) → 1000 pts
//             Dee   61000ms → round(1000 * 59000 / 61000) = 967
//             (without override, Cam's faster R2=57000ms would give Dee 934 pts instead)
//
//  Event 4 / C1  fastest = 53000ms (Alex) → 1000 pts
//             Bea   57000ms → round(1000 * 53000 / 57000) = 930
//  Event 4 / CS  fastest = 62000ms (Dee)  → 1000 pts (off-class for Dee; excluded)
//
//  Event 5 / C1  fastest = 56000ms (Alex, 54000+2000 cone) → 1000 pts
//  Event 5 / CS  Bea   60000ms → off-class for Bea; excluded
//             Cam   DNF        → no CLEAN run (exercises CLEAN filter)
//
// Alex's C1 scores: 1000 * 5 → best 4 = 4000; 1 dropped.
// Bea's  C1 scores: 909, 962, 963, 930 → total = 3764 (all 4 counted; her CS entry at event 5 excluded)
// Cam's  CS scores: 1000, 1000, 1000   → total = 3000; eligible=false (3 < 4)
// Dee's  C1 scores: 833, 911           → total = 1744 (2 events, tiebreak to C1, CS entries excluded)
// Evan's C1 scores: 806                → total = 806; eligible=false (1 < 4)

import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";
import { rmSync } from "node:fs";
import Database from "better-sqlite3";

const here = dirname(fileURLToPath(import.meta.url));

const SCHEMA = `
  CREATE TABLE 'events' (
    id              INTEGER PRIMARY KEY AUTOINCREMENT,
    event_name      VARCHAR(40) NOT NULL,
    event_date      DATE        NOT NULL,
    num_runs        INTEGER     NOT NULL,
    mirrored        BOOLEAN     NOT NULL,
    unique_numbers  BOOLEAN     NOT NULL,
    org_name        VARCHAR(40) NOT NULL,
    timing_mode     INTEGER     NOT NULL,
    typical_time    FLOAT       NOT NULL,
    web_active      BOOLEAN     NOT NULL,
    run_timestamp   INTEGER
  );

  CREATE TABLE 'classes' (
    id              INTEGER PRIMARY KEY AUTOINCREMENT,
    class_name      VARCHAR(20) NOT NULL UNIQUE,
    paxed_class     BOOLEAN DEFAULT 0  NOT NULL,
    pax             FLOAT   DEFAULT "1.0" NOT NULL,
    run_timestamp   INTEGER
  );
  CREATE INDEX 'idx_classes_class_name' ON 'classes' (class_name);

  CREATE TABLE 'drivers' (
    id              INTEGER PRIMARY KEY AUTOINCREMENT,
    last_name       VARCHAR(30) NOT NULL,
    first_name      VARCHAR(30) NOT NULL,
    number          VARCHAR(6)  NOT NULL,
    class_id        INTEGER     NOT NULL,
    paxmult_id      INTEGER     NOT NULL,
    car_model       VARCHAR(40),
    car_color       VARCHAR(20),
    member_num      VARCHAR(30),
    sponsor         VARCHAR(40),
    tire            VARCHAR(40),
    email           VARCHAR(60),
    cellphone       VARCHAR(20),
    member          BOOLEAN,
    registered      BOOLEAN,
    icon_color      VARCHAR(20),
    FOREIGN KEY (class_id)   REFERENCES classes ON UPDATE RESTRICT ON DELETE RESTRICT,
    FOREIGN KEY (paxmult_id) REFERENCES classes ON UPDATE RESTRICT ON DELETE RESTRICT
  );
  CREATE INDEX 'idx_drivers_number'     ON 'drivers' (number);
  CREATE INDEX 'idx_drivers_class_id'   ON 'drivers' (class_id);
  CREATE INDEX 'idx_drivers_last_name'  ON 'drivers' (last_name);
  CREATE INDEX 'idx_drivers_first_name' ON 'drivers' (first_name);

  CREATE TABLE 'registrations' (
    driver_id            INTEGER NOT NULL,
    event_id             INTEGER NOT NULL,
    bestcommittedrun_id  INTEGER,
    bestcommittedrun_no  INTEGER,
    bestpendingrun_id    INTEGER,
    run_timestamp        INTEGER,
    FOREIGN KEY (driver_id) REFERENCES drivers ON UPDATE RESTRICT ON DELETE RESTRICT,
    FOREIGN KEY (event_id)  REFERENCES events  ON UPDATE RESTRICT ON DELETE RESTRICT
  );
  CREATE INDEX 'idx_registrations_driver_id' ON 'registrations' (driver_id);
  CREATE INDEX 'idx_registrations_event_id'  ON 'registrations' (event_id);

  CREATE TABLE 'runs' (
    id           INTEGER PRIMARY KEY AUTOINCREMENT,
    event_id     INTEGER NOT NULL,
    driver_id    INTEGER NOT NULL,
    start_at     INTEGER,
    finish_at    INTEGER,
    start_tick   INTEGER,
    finish_tick  INTEGER,
    cones        INTEGER,
    disposition  VARCHAR(10),
    status       INTEGER NOT NULL,
    FOREIGN KEY (event_id)  REFERENCES events  ON UPDATE RESTRICT ON DELETE RESTRICT,
    FOREIGN KEY (driver_id) REFERENCES drivers ON UPDATE RESTRICT ON DELETE RESTRICT
  );
  CREATE INDEX 'idx_runs_driver_id' ON 'runs' (driver_id);
  CREATE INDEX 'idx_runs_event_id'  ON 'runs' (event_id);
`;

/**
 * Build a single-event .axdb fixture.
 * @param {string} filename - output filename (no path)
 * @param {string} eventName
 * @param {string} eventDate  - "YYYY-MM-DD"
 * @param {number} eventTs    - Unix timestamp for event
 * @param {Array}  classes    - [{id, name, paxed, pax}]
 * @param {Array}  drivers    - [{id, last, first, num, classId, paxId, memberNum}]
 * @param {Array}  runs       - [{driverId, deltaMs, cones, disposition}]
 * @param {Map|null} overrides - Map<driverId, bestcommittedrun_no> for committed-run overrides.
 *                               Drivers not in the map get bestcommittedrun_no pointing to
 *                               run #1 (the only run for most drivers in this fixture).
 */
function buildEventAxdb(filename, eventName, eventDate, eventTs, classes, drivers, runs, overrides = null) {
  const out = join(here, filename);
  rmSync(out, { force: true });

  const db = new Database(out);
  db.pragma("journal_mode = DELETE");
  db.pragma("foreign_keys = OFF");
  db.exec(SCHEMA);

  const insertEvent = db.prepare(`
    INSERT INTO events (event_name, event_date, num_runs, mirrored, unique_numbers, org_name, timing_mode, typical_time, web_active, run_timestamp)
    VALUES (?, ?, ?, 0, 0, ?, 0, ?, 1, ?)
  `);
  const insertClass = db.prepare(`INSERT INTO classes (class_name, paxed_class, pax, run_timestamp) VALUES (?, ?, ?, ?)`);
  const insertDriver = db.prepare(`
    INSERT INTO drivers (last_name, first_name, number, class_id, paxmult_id, car_model, car_color, member_num, sponsor, tire, email, cellphone, member, registered, icon_color)
    VALUES (?, ?, ?, ?, ?, ?, ?, ?, '', '', '', '', 1, 1, 'red')
  `);
  const insertReg = db.prepare(`
    INSERT INTO registrations (driver_id, event_id, bestcommittedrun_id, bestcommittedrun_no, run_timestamp)
    VALUES (?, 1, ?, ?, ?)
  `);
  const insertRun = db.prepare(`
    INSERT INTO runs (event_id, driver_id, start_at, finish_at, start_tick, finish_tick, cones, disposition, status)
    VALUES (1, ?, ?, ?, ?, ?, ?, ?, 3)
  `);
  const lastRowId = db.prepare("SELECT last_insert_rowid() AS id");

  db.transaction(() => {
    insertEvent.run(eventName, eventDate, 6, "RMR Synthetic", 55.0, eventTs);

    for (const c of classes) {
      insertClass.run(c.name, c.paxed ? 1 : 0, c.pax, eventTs);
    }

    for (const d of drivers) {
      insertDriver.run(d.last, d.first, d.num, d.classId, d.paxId, d.car ?? null, d.color ?? null, d.memberNum ?? null);
    }

    // Insert runs and track (driverId → [{runId, runNo}]) for registration population.
    const runsByDriver = new Map();
    let wallSec = eventTs + 1800;
    let tick = 5_000_000;

    for (const r of runs) {
      const isClean = !r.disposition || r.disposition === "";
      insertRun.run(
        r.driverId,
        wallSec,
        wallSec + (isClean ? Math.ceil(r.deltaMs / 1000) : 1),
        tick,
        isClean ? tick + r.deltaMs : tick + 1,
        r.cones ?? 0,
        r.disposition ?? "",
      );
      const runId = lastRowId.get().id;
      const list = runsByDriver.get(r.driverId) ?? [];
      list.push({ runId, runNo: list.length + 1 });
      runsByDriver.set(r.driverId, list);
      wallSec += 60;
      tick += 90_000;
    }

    // Insert registrations with bestcommittedrun_id and bestcommittedrun_no.
    // For drivers in overrides map, use the specified run number.
    // For all others, point to run #1 (default — all single-run drivers).
    for (const d of drivers) {
      const driverRuns = runsByDriver.get(d.id) ?? [];
      const overrideNo = overrides?.get(d.id) ?? null;
      const commitNo = overrideNo ?? (driverRuns.length > 0 ? 1 : null);
      const commitEntry = driverRuns.find((r) => r.runNo === commitNo);
      const commitId = commitEntry?.runId ?? null;
      insertReg.run(d.id, commitId, commitNo, eventTs);
    }
  })();

  const counts = {
    events: db.prepare("SELECT COUNT(*) AS n FROM events").get().n,
    drivers: db.prepare("SELECT COUNT(*) AS n FROM drivers").get().n,
    runs: db.prepare("SELECT COUNT(*) AS n FROM runs").get().n,
  };
  db.close();
  console.log(`Wrote ${filename}`, counts);
}

// ─── Class definitions (same across all events) ─────────────────────────────
const ALL_CLASSES = [
  { id: 1, name: "C1", paxed: false, pax: 1.0 },
  { id: 2, name: "CS", paxed: true,  pax: 0.92 },
];

// ─── Event 1: 2026-03-01 ─────────────────────────────────────────────────────
// C1: Alex=50000, Bea=55000, Dee=60000, Evan=62000
// CS: Cam=57000
buildEventAxdb(
  "season-event-1.axdb",
  "Season Event 1",
  "2026-03-01",
  1772485200,
  ALL_CLASSES,
  [
    { id: 1, last: "Arena",  first: "Alex", num: "101", classId: 1, paxId: 1, memberNum: "MES-001" },
    { id: 2, last: "Barton", first: "Bea",  num: "102", classId: 1, paxId: 1, memberNum: "MES-002" },
    { id: 3, last: "Crane",  first: "Cam",  num: "103", classId: 2, paxId: 2, memberNum: "MES-003" },
    { id: 4, last: "Dumas",  first: "Dee",  num: "104", classId: 1, paxId: 1, memberNum: "MES-004" },
    { id: 5, last: "Elias",  first: "Evan", num: "105", classId: 1, paxId: 1, memberNum: "MES-005" },
  ],
  [
    { driverId: 1, deltaMs: 50000, cones: 0 },
    { driverId: 2, deltaMs: 55000, cones: 0 },
    { driverId: 3, deltaMs: 57000, cones: 0 },
    { driverId: 4, deltaMs: 60000, cones: 0 },
    { driverId: 5, deltaMs: 62000, cones: 0 },
  ],
);

// ─── Event 2: 2026-04-05 ─────────────────────────────────────────────────────
// C1: Alex=51000, Bea=53000, Dee=56000
// CS: Cam=58000
buildEventAxdb(
  "season-event-2.axdb",
  "Season Event 2",
  "2026-04-05",
  1775127600,
  ALL_CLASSES,
  [
    { id: 1, last: "Arena",  first: "Alex", num: "101", classId: 1, paxId: 1, memberNum: "MES-001" },
    { id: 2, last: "Barton", first: "Bea",  num: "102", classId: 1, paxId: 1, memberNum: "MES-002" },
    { id: 3, last: "Crane",  first: "Cam",  num: "103", classId: 2, paxId: 2, memberNum: "MES-003" },
    { id: 4, last: "Dumas",  first: "Dee",  num: "104", classId: 1, paxId: 1, memberNum: "MES-004" },
  ],
  [
    { driverId: 1, deltaMs: 51000, cones: 0 },
    { driverId: 2, deltaMs: 53000, cones: 0 },
    { driverId: 3, deltaMs: 58000, cones: 0 },
    { driverId: 4, deltaMs: 56000, cones: 0 },
  ],
);

// ─── Event 3: 2026-05-10 ─────────────────────────────────────────────────────
// C1: Alex=52000, Bea=54000
// CS: Cam has two runs — R1=59000ms (committed), R2=57000ms (faster clean)
//     bestcommittedrun override: Cam's committed best is R1 (59000ms), not R2 (57000ms).
//     Dee=61000ms (single run, no override)
buildEventAxdb(
  "season-event-3.axdb",
  "Season Event 3",
  "2026-05-10",
  1778374800,
  ALL_CLASSES,
  [
    { id: 1, last: "Arena",  first: "Alex", num: "101", classId: 1, paxId: 1, memberNum: "MES-001" },
    { id: 2, last: "Barton", first: "Bea",  num: "102", classId: 1, paxId: 1, memberNum: "MES-002" },
    { id: 3, last: "Crane",  first: "Cam",  num: "103", classId: 2, paxId: 2, memberNum: "MES-003" },
    { id: 4, last: "Dumas",  first: "Dee",  num: "104", classId: 2, paxId: 2, memberNum: "MES-004" }, // CS
  ],
  [
    { driverId: 1, deltaMs: 52000, cones: 0 },
    { driverId: 2, deltaMs: 54000, cones: 0 },
    { driverId: 3, deltaMs: 59000, cones: 0 }, // R1: committed best (slower)
    { driverId: 3, deltaMs: 57000, cones: 0 }, // R2: faster clean (should be overridden)
    { driverId: 4, deltaMs: 61000, cones: 0 },
  ],
  // Override: Cam's committed run is R1 (59000ms), not R2 (57000ms, faster clean).
  new Map([[3, 1]]),
);

// ─── Event 4: 2026-06-14 ─────────────────────────────────────────────────────
// C1: Alex=53000, Bea=57000
// CS: Dee=62000  ← Dee still in CS
buildEventAxdb(
  "season-event-4.axdb",
  "Season Event 4",
  "2026-06-14",
  1781521200,
  ALL_CLASSES,
  [
    { id: 1, last: "Arena",  first: "Alex", num: "101", classId: 1, paxId: 1, memberNum: "MES-001" },
    { id: 2, last: "Barton", first: "Bea",  num: "102", classId: 1, paxId: 1, memberNum: "MES-002" },
    { id: 4, last: "Dumas",  first: "Dee",  num: "104", classId: 2, paxId: 2, memberNum: "MES-004" }, // CS
  ],
  [
    { driverId: 1, deltaMs: 53000, cones: 0 },
    { driverId: 2, deltaMs: 57000, cones: 0 },
    { driverId: 4, deltaMs: 62000, cones: 0 },
  ],
);

// ─── Event 5: 2026-07-19 ─────────────────────────────────────────────────────
// C1: Alex=54000 + 1 cone → corrected 56000 (only scorer → 1000 pts)
// CS: Bea=60000 (off-class), Cam=DNF (exercises CLEAN filter)
buildEventAxdb(
  "season-event-5.axdb",
  "Season Event 5",
  "2026-07-19",
  1784732400,
  ALL_CLASSES,
  [
    { id: 1, last: "Arena",  first: "Alex", num: "101", classId: 1, paxId: 1, memberNum: "MES-001" },
    { id: 2, last: "Barton", first: "Bea",  num: "102", classId: 2, paxId: 2, memberNum: "MES-002" }, // CS
    { id: 3, last: "Crane",  first: "Cam",  num: "103", classId: 2, paxId: 2, memberNum: "MES-003" },
  ],
  [
    { driverId: 1, deltaMs: 54000, cones: 1 },            // C1: 54000 + 2000 cone = 56000
    { driverId: 2, deltaMs: 60000, cones: 0 },            // CS: off-class for Bea
    { driverId: 3, deltaMs: 70000, cones: 0, disposition: "DNF" }, // CS: DNF → excluded
  ],
);

console.log("Done. Run `pnpm --filter web test` to verify.");
